    lines = s.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    visited = [False] * (n + 1)
    components = []

    from collections import deque

    for i in range(1, n + 1):
        if not visited[i]:
            visited[i] = True
            comp_size = 0
            queue = deque([i])
            while queue:
                node = queue.popleft()
                comp_size += 1
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append(neighbor)
            components.append(comp_size)

    if len(components) == 0:
        return "-1\n"

    def is_lucky(num):
        s = str(num)
        for c in s:
            if c not in '47':
                return False
        return True

    lucky_numbers = []
    for i in range(1, n + 1):
        if is_lucky(i):
            lucky_numbers.append(i)

    # BFS/DP approach: for each reachable sum, track minimum components needed
    dp = {}
    for size in components:
        if size not in dp:
            dp[size] = 1
        else:
            dp[size] = min(dp.get(size, float('inf')), 1)

        # Try to update all existing sums
        to_update = list(dp.keys()) if dp else []
        for existing_sum, count in to_update.items():
            new_sum = existing_sum + size
            if new_sum not in dp:
                dp[new_sum] = count + 1
            else:
                dp[new_sum] = min(dp[new_sum], count + 1)

    # If a single component is already lucky, we need 0 roads
    min_roads = float('inf')

    for lucky in lucky_numbers:
        if lucky in dp:
            min_roads = min(min_roads, dp[lucky] - 1)

    return "-1\n" if min_roads == float('inf') else f"{min_roads}\n"

