def solution(input_str):
    import sys
    from collections import defaultdict, deque

    lines = input_str.strip().split('\n')
    first_line = lines[0].split()
    n, m = int(first_line[0]), int(first_line[1])

    adj = defaultdict(list)
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    x = list(map(int, lines[m + 1].split()))

    # Count vertices requiring even/odd visits
    odd_nodes = [i + 1 for i, val in enumerate(x) if val == 1]

    # If no nodes need odd visits, empty path is valid
    if not odd_nodes:
        return "0\n"

    # Special case: when there's only one odd node and no edges
    if len(odd_nodes) == 1 and m == 0:
        return "1\n" + str(odd_nodes[0]) + "\n"

    # Build path using BFS
    def find_path(start, end):
        visited = {start}
        parent = {start: None}
        queue = deque([start])

        while queue:
            curr = queue.popleft()
            if curr == end:
                path = []
                node = end
                while node is not None:
                    path.append(node)
                    node = parent[node]
                return list(reversed(path))

            for neighbor in adj[curr]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    parent[neighbor] = curr
                    queue.append(neighbor)

        return []

    # Build path visiting odd nodes as endpoints
    start_node = odd_nodes[0]
    end_node = odd_nodes[-1]

    result_path = find_path(start_node, end_node)

    if not result_path:
        return "-1\n"

    # Check if path satisfies parity constraints
    count = defaultdict(int)
    for node in result_path:
        count[node] += 1

    valid = True
    for i in range(1, n + 1):
        visits = count[i]
        if x[i - 1] == 1 and visits % 2 == 0:
            valid = False
            break
        if x[i - 1] == 0 and visits % 2 == 1:
            valid = False
            break

    if valid and len(result_path) <= 4 * n:
        return f"{len(result_path)}\n" + " ".join(map(str, result_path)) + "\n"

    return "-1\n"

