def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    # fib[i] = Fibonacci with f[0]=1, f[1]=1, f[2]=2, ...
    max_idx = n + 500
    fib = [1, 1]
    for i in range(2, max_idx + 1):
        fib.append((fib[-1] + fib[-2]) % MOD)

    # fib_sum[k] = sum(fib[0] to fib[k-1])
    fib_sum = [0] * (max_idx + 2)
    for i in range(1, len(fib_sum)):
        if i - 1 < len(fib):
            fib_sum[i] = (fib_sum[i-1] + fib[i-1]) % MOD
        else:
            fib_sum[i] = fib_sum[i-1]

    # Segment tree arrays
    size = 1
    while size < n:
        size *= 2
    tree_sum = [0] * (2 * size)
    tree_w = [0] * (2 * size)
    lazy = [0] * (2 * size)

    def fib_sum_count(l, r):
        if l > r:
            return 0, 0
        # sum from fib indices l-1 to r-1
        return r - l + 1, fib_sum[r] - fib_sum[l-1]

    def pull(node):
        tree_sum[node] = (tree_sum[node*2] + tree_sum[node*2+1]) % MOD
        tree_w[node] = (tree_w[node*2] + tree_w[node*2+1]) % MOD

    for i in range(n):
        idx = size + i
        tree_sum[idx] = a[i]
        tree_w[idx] = (a[i] * fib[i]) % MOD

    for i in range(size - 1, 0, -1):
        pull(i)

    def push(node, l, r):
        if lazy[node] == 0:
            return
        mid = (l + r) // 2
        size_left = mid - l + 1
        size_right = r - mid

        # Left child [l, mid], fib indices [l-1, mid-1]
        cnt_l, w_l = fib_sum_count(l, mid)
        # Right child [mid+1, r], fib indices [mid, r-1]
        cnt_r, w_r = fib_sum_count(mid+1, r)

        left, right = node*2, node*2+1

        tree_sum[left] = (tree_sum[left] + lazy[node] * size_left) % MOD
        tree_w[left] = (tree_w[left] + (lazy[node] * w_l) % MOD) % MOD
        lazy[left] = (lazy[left] + lazy[node]) % MOD

        tree_sum[right] = (tree_sum[right] + lazy[node] * size_right) % MOD
        tree_w[right] = (tree_w[right] + (lazy[node] * w_r) % MOD) % MOD
        lazy[right] = (lazy[right] + lazy[node]) % MOD

        lazy[node] = 0

    def query(node, l, r, ql, qr):
        if ql <= l and r <= qr:
            return tree_w[node]

        push(node, l, r)
        mid = (l + r) // 2

        if qr <= mid:
            return query(node*2, l, mid, ql, qr)
        elif ql > mid:
            return query(node*2+1, mid+1, r, ql, qr)
        else:
            return (query(node*2, l, mid, ql, mid) + 
                    query(node*2+1, mid+1, r, mid+1, qr)) % MOD

    def update(node, l, r, ql, qr, val):
        if ql <= l and r <= qr:
            size_left = r - l + 1
            cnt, w = fib_sum_count(l, r)
            tree_sum[node] = (tree_sum[node] + val * size_left) % MOD
            tree_w[node] = (tree_w[node] + (val * w) % MOD) % MOD
            return

        push(node, l, r)
        mid = (l + r) // 2

        if ql <= mid:
            update(node*2, l, mid, ql, qr, val)
        if qr > mid:
            update(node*2+1, mid+1, r, ql, qr, val)

        pull(node)

    def point_set(node, l, r, pos, val):
        if l == r:
            tree_sum[node] = val
            tree_w[node] = (val * fib[l]) % MOD
            return

        push(node, l, r)
        mid = (l + r) // 2

        if pos <= mid:
            point_set(node*2, l, mid, pos, val)
        else:
            point_set(node*2+1, mid+1, r, pos, val)

        pull(node)

    old_a = a[:]

    results = []
    for line in lines[2:]:
        parts = list(map(int, line.split()))
        t = parts[0]
        if t == 1:
            x, v = parts[1], parts[2]
            point_set(1, 1, n, x, v)
        elif t == 2:
            l, r = parts[1], parts[2]
            result = query(1, 1, n, l, r)
            results.append(str(result))
        elif t == 3:
            l, r, d = parts[1], parts[2], parts[3]
            update(1, 1, n, l, r, d)

    return '\n'.join(results)


