    k = int(lines[0])
    a = list(map(int, lines[1].split()))
    n = 2 ** k

    used_p = [False] * n
    used_q = [False] * n
    p = [0] * n
    q = [0] * n

    def backtrack(idx):
        if idx == n:
            return True

        for val in range(n):
            if not used_q[val]:
                p_val = a[idx] ^ val
                if not used_p[p_val]:
                    used_q[val] = True
                    used_p[p_val] = True
                    p[idx] = p_val
                    q[idx] = val

                    if backtrack(idx + 1):
                        return True

                    used_q[val] = False
                    used_p[p_val] = False

        return False

    if backtrack(0):
        return "Shi\n" + " ".join(map(str, p)) + "\n" + " ".join(map(str, q))
    else:
