def solution(input_data: str):
    lines = input_data.strip().split('\n')
    n = int(lines[0])
    students = lines[1:n+1]
    pseudonyms = lines[n+1:2*n+1]

    total_quality = 0
    matches = []

    class TrieNode:
        __slots__ = ['children', 's_set', 'p_set', 's_count', 'p_count', 's_list', 'p_list']
        def __init__(self):
            self.children = {}
            self.s_count = 0
            self.p_count = 0
            self.s_list = []
            self.p_list = []

    root = TrieNode()

    def insert(name, is_student, idx):
        node = root
        if is_student:
            node.s_count += 1
            node.s_list.append(idx)
        else:
            node.p_count += 1
            node.p_list.append(idx)

        for char in name:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
            if is_student:
                node.s_count += 1
            else:
                node.p_count += 1

    for i in range(n):
        insert(students[i], True, i)
    for i in range(n):
        insert(pseudonyms[i], False, i)

    def dfs(node, path_s, path_p, matches):
        nonlocal total_quality

        if node.s_count <= 0 or node.p_count <= 0:
            return

        if not node.s_list or not node.p_list:
            return

        st_list = node.s_list[:node.s_count]
        ps_list = node.p_list[:node.p_count]

        # Match greedily
        if node.s_count > 0 and node.p_count > 0:
            match_count = min(node.s_count, node.p_count)
            for i in range(match_count):
                si = st_list[i % len(node.s_list)]
                pi = ps_list[i % len(node.p_list)]
                if matches[si] == False and matches[pi] == False:
                    matches[si] = True
                    matches[pi] = True
                    total_quality += len(most_similar(si, pi))
                    result.append((si + 1, pi + 1))

        for char, child in node.children.items():
            dfs(child, path_s + [char], path_p + [char], matches)

    def most_similar(si, pi):
        # Find LCP
        s = students[si]
        p = pseudonyms[pi - n]
        i = 0
        while i < len(s) and i < len(p) and s[i] == p[i]:
            i += 1
        return i

    # DFS matching
    for char, child in root.children.items():
        dfs(child)

    output_lines = [str(total_quality)]
    for a, b in result:
        output_lines.append(f"{a} {b}")

    return '\n'.join(output_lines)

