    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        i = 3
        while i * i <= num:
            if num % i == 0:
                return False
            i += 2
        return True

    if not is_prime(p):
        return "-1\n"

    # Modular exponentiation
    def power(a, b, m):
        result = 1
        a %= m
        while b > 0:
            if b % 2 == 1:
                result = (result * a) % m
            a = (a * a) % m
            b //= 2
        return result

    # Prime factorization of n = p - 1
    prime_factors = set()
    temp = n
    d = 2
    while d * d <= temp:
        while temp % d == 0:
            prime_factors.add(d)
            temp //= d
        d += 1
