import sys

def BFS(start, adj, n):
    """Returns distances from start to all other nodes."""
    distances = [-1] * (n + 1)
    distances[start] = 0
    queue = deque([start])

    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if distances[v] == -1:
                distances[v] = distances[u] + 1
                queue.append(v)
    return distances

