class Parser:
    def __init__(self, s):
        self.s = s
        self.pos = 0

    def parse_expression(self):
        left, left_end = self.parse_term()

        while self.pos < len(self.s) and self.s[self.pos] == '+':
            self.pos += 1
            term, term_end = self.parse_term()
            if isinstance(left, tuple):
                left = (left[0] + term) % MOD
                left_end += term_end - self.pos + len(left[1])
            else:
                left = (left + term) % MOD
                left_end += term_end

        return (left % MOD, left_end)

    def parse_term(self):
        # Find where this term ends (until next operator or end)
        i = self.pos
        while i < len(self.s):
            if self.s[i] in '+-(: ':
                break
            i += 1

        end = i

        # Skip leading whitespace
        while self.pos < end and self.pos < len(self.s) and self.s[self.pos].isspace():
            self.pos += 1
        if self.pos >= end:
            return (0, 0)

        # Check for repetition: number(repetition)
        if self.pos < end and self.s[self.pos] == '(':
            # Find where the number ends
            num_start = self.pos
            num_end = num_start
            while num_end < end and self.s[num_end].isdigit():
                num_end += 1

            # Parse the number
            num_value = int(self.s[num_start:num_end])
            num_len = num_end - num_start

            # Skip the space if present
            self.pos = num_end
            if self.pos < end and self.s[self.pos] == '(':
                self.pos += 1

            # Parse the expression inside parentheses
            expr_val, expr_len = self.parse_expression()

            # Skip to ')'
            space_count = sum(1 for c in self.s[self.pos+1:if self.pos < len(self.s):
                self.pos = self.pos + 1
            if self.s[self.pos] == ')':
                self.pos += 1

            # Result is expr repeated num_value times
            if num_value > 1:
                # Concatenating expr num_value times
                result_val = expr_val
                for _ in range(num_value - 1):
                    result_val = (result_val * (10 ** expr_len % MOD) + expr_val) % MOD
            else:
                result_val = expr_val

            return (result_val, expr_len * num_value)

        # Parse number until '-'
        num_start = self.pos
        num_end = num_start
        while num_end < end and self.s[num_end].isdigit():
            num_end += 1

        num_len = num_end - num_start
        num_value = int(self.s[num_start:num_end])

        self.pos = num_end

        # Check if this was just a number or a range
        if self.pos < end and self.s[self.pos] == '-':
            self.pos += 1

            # Parse the second number
            start2 = self.pos
            end2 = start2
            while end2 < end and self.s[end2].isdigit():
                end2 += 1

            num2_len = end2 - start2
            num2_value = int(self.s[start2:end2])

            # Concatenate all numbers from num_value to num2_value
            result = ""
            for i in range(num_value, num2_value + 1):
                result += str(i)

            result_val = int(result)
        else:
            result_val = num_value

        return (result_val % MOD, len(str(int(result_val))))


def parse_expression(input_str):
    MOD = 10**9 + 7
    parser = Parser(input_str)
    value, length = parser.parse_expression()
    return (value % MOD, length)


