    def is_bounded(m):
        """Check if polynomial with monomials m has positive coefficients is bounded from below."""
        if not m:
            return True

        max_degree = max(a + b for a, b in m)

        def check_odd_power(a, b, check_x):
            """Returns True if term (a,b) is compensated for the odd power in the given variable."""
            # Check if we need compensation
            if check_x:  # Check if a is odd
                if a % 2 == 0:
                    return True  # Even power, no compensation needed
            else:  # Check if b is odd
                if b % 2 == 0:
                    return True  # Even power, no compensation needed

            # Need compensation: either a > b's odd variable or b > x's odd variable with appropriate conditions
            if check_x:  # a is odd, need a' > a with a' + b' >= a + b
                for a2, b2 in m:
                    if a2 > a and a2 + b2 >= a + b:
                        return True
            else:  # b is odd, need b' > b with a' + b' >= a + b
                for a2, b2 in m:
                    if b2 > b and a2 + b2 >= a + b:
                        return True

            return False

        for a, b in m:
            if a + b < max_degree:
                continue

            # Check compensation for both a and b being odd
            if a % 2 == 1 and not check_odd_power(a, b, True):
                return False
            if b % 2 == 1 and not check_odd_power(a, b, False):
