            dfs_bridge(i)

    if has_bridge:
        return "0\n"

    # Orient edges: tree edges parent->child, back edges child->ancestor
    result = [None] * m

    def dfs_orient(u):
        for v, idx in adj[u]:
            if result[idx] is None:
                # Tree edge: orient from current to next
                result[idx] = (u, v)
                dfs_orient(v)

    dfs_orient(1)

    # Build output
    output_lines = []
    for i in range(m):
        if result[i] is not None:
            u, v = result[i]
            output_lines.append(f"{u} {v}")

    return '\n'.join(output_lines) + '\n'

