    # dp[0] = {balance: list of paths}
    dp = {(0, [str(i) for i in range(n)]): ['L', 'D', 'L'] if k == 2 else []}

    # Initialize: at position 0, balance is 0
    dp = {0: ['']}

    # Process each character
    for i in range(n):
