        for balance, paths in dp.items():
            # Check constraint before processing this hand
            if abs(balance) == k:
                continue

            char = s[i]
            choices = []
            if char == '?':
                choices = [(1, 'W'), (-1, 'L'), (0, 'D')]
            elif char == 'W':
                choices = [(1, 'W')]
            elif char == 'L':
                choices = [(-1, 'L')]
            else:  # 'D'
                choices = [(0, 'D')]

            for change, c in choices:
                new_balance = balance + change
                if new_balance not in next_dp:
                    next_dp[new_balance] = []
                for p in paths:
                    next_dp[new_balance].append(p + c)

        dp = next_dp

    # Check for valid ending (|balance| == k)
    result = None
    for balance, paths in dp.items():
        if abs(balance) == k and paths:
            result = paths[0]
            break

    if result is None:
        return 'NO\n'
    return result + '\n'

