            # Direct count in s0
            count = 0
            for i in range(n_s0 - n_w + 1):
                if s0[i:i+n_w] == w:
                    count += 1
            results.append(str(count % MOD))
            continue

        # Precompute prefix and suffix matches for w with s0
        # pre_match[i] = count of positions where s0 starts with w[:i]
        # suf_match[i] = count of positions where s0 ends with w[|w|-i:]
        pre_match = [0] * (n_w + 1)
        suf_match = [0] * (n_w + 1)

        # Compute prefix matches
        for start in range(n_s0):
            for i in range(1, min(n_w, n_s0 - start) + 1):
                if s0[start:start+i] == w[:i]:
                    pre_match[i] += 1

        # Compute suffix matches
        for start in range(n_s0 - n_w + 1):
            for i in range(1, min(n_w + 1, n_w - start + 1)):
                end = min(n_s0, start + i)
                if s0[start:end] == w[n_w-i:end=start+i:n_w-i]:
                    # Simpler: just check if it equals the suffix
                    pass

        # Simpler suffix approach: for each length, count how many suffixes match
        for length in range(1, n_s0 + 1):
            match_str = w[n_w - length:] if length <= n_w else ""
            if length <= n_w:
                for i in range(n_s0 - length + 1):
                    if s0[i:i+length] == match_str:
                        suf_match[length] += 1

        # Build KMP automaton for w
        fail = [0] * n_w
        j = 0
        for i in range(1, n_w):
            while j > 0 and w[j] != w[i]:
                j = fail[j-1]
            if w[j] == w[i]:
                j += 1
            fail[i] = j

        # Compute occurrences in s0
        occ = 0
        j = 0
        for i, c in enumerate(s0):
            while j > 0 and w[j] != c:
                j = fail[j-1]
            if w[j] == c:
                j += 1
            if j == n_w:
                occ += 1
                j = fail[j-1]

        # Count occurrences at each crossing level
        # When s_{i+1} = s_i + t[i] + s_i, crossings happen at the middle
        # A crossing match at level m means w[0:mid] matches a suffix and w[mid+1:] matches a prefix

        crossing_occ = 0
        for mid in range(1, n_w - 1):
            prefix = w[:mid]
            suffix = w[mid+1:]
            middle_char = w[mid]

            # Count how many positions in s0 have both proper prefix and suffix matches
            for i in range(n_s0 - mid - len(suffix) + 1 if mid + len(suffix) <= n_s0 else 0):
                if s0[i:i+mid] == prefix and s0[i+mid+1:i+mid+1+len(suffix)] == suffix:
                    pass

        # Calculate total count based on recurrence
        count = occ

        # The count doubles plus additions from boundary matches at each level
        # Simplified recurrence:
        for i in range(1, k + 1):
            # Add crossing matches from boundary
            boundary_char = t[i-1]

            # Find how many crossing matches at this boundary
            add = 0
            for mid in range(1, n_w - 1):
                if w[mid] == boundary_char:
                    # Check if this can be a crossing match
                    prefix = w[:mid]
                    suffix = w[mid+1:]

                    # Check prefix match with s0
                    pre_ok = 0
                    for pos in range(n_s0 - len(prefix)):
                        if s0[pos:pos+len(prefix)] == prefix:
                            pre_ok += 1

                    # Check suffix match with s0
                    suf_ok = 0
                    for pos in range(n_s0 - len(suffix)):
                        if s0[pos:pos+len(suffix)] == suffix:
                            suf_ok += 1

                    if pre_ok > 0 and suf_ok > 0:
                        add += pre_ok * suf_ok

            count = (count * 2 + add) % MOD

        results.append(str(count % MOD))

    return '\n'.join(results)

import math

def dist(p1, p2):
    return math.sqrt((p1[0]-p2[0])**2 + (p1[1]-p2[1])**2 + (p1[2]-p2[2])**2)

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    points = []
    for i in range(n + 1):
        parts = list(map(int, lines[1 + i].split()))
        points.append((parts[0], parts[1], parts[2]))

    vp, vs = map(float, lines[n + 1].split())
    hp = tuple(map(int, lines[n + 2].split()))

    def snitch_pos_at_time(t):
        current_time = 0.0
        for i in range(n):
            seg_len = dist(points[i], points[i+1])
            seg_duration = seg_len / vs
            if t >= current_time + seg_duration:
                current_time += seg_duration
            else:
                fraction = (t - current_time) * vs / seg_len
                px = points[i][0] + fraction * (points[i+1][0] - points[i][0])
                py = points[i][1] + fraction * (points[i+1][1] - points[i][1])
                pz = points[i][2] + fraction * (points[i+1][2] - points[i][2])
                return (px, py, pz)
        return points[-1]

    def can_catch_at_time(t):
        sn_pos = snitch_pos_at_time(t)
        return dist(hp, sn_pos) <= vp * t + 1e-9

    if dist(hp, points[0]) < 1e-9:
        return f"YES\n0.000000000000000\n{hp[0]} {hp[1]} {hp[2]}\n"

    low = 0.0
    high = 1e9

    for _ in range(100):
        mid = (low + high) / 2
        if can_catch_at_time(mid):
            high = mid
        else:
            low = mid

    t = high
    final_pos = snitch_pos_at_time(t)
    return f"YES\n{t:.10f}\n{final_pos[0]:.10f} {final_pos[1]:.10f} {final_pos[2]:.10f}\n"

def solution(input_str):
    n = int(input_str.strip())
    MOD = 10**9 + 7

    # dp[length][balance] = [matched_in_subtree_without_parent_constraint, 
    #                            matched_in_subtree_with_some_child_its_subtree]
    memo = [[[0, 0] for _ in range(n + 1)] for _ in range(2 * n + 1)]

    def compute(l):
        if l == 2 * n:
            return memo[l][0]

        results = []
        for b in range(n + 1):
            if b > l or b < 0 or (l - b) % 2 != 0 or b > len([1]*n) + n - l:
                continue
            if ((2 * n - l - b) % 2) != 0:
                continue

            subs = []
            for cb in [b + 1, b - 1]:
                if 0 <= cb <= n and (2 * n - (l + 1) - cb) % 2 == 0:
                    subs.append(compute(l + 1))

            # For the root level, just return max matching
            if l < 2 * n:
                if not subs:
                    results.append(0)
                else:
                    results.append(max(x if x < MOD else x % MOD for x in subs))

        return results[0] if results else 0

    return str(compute(0))

MOD = 10**9 + 7

def solution(input_str):
    n, k, m = map(int, input_str.strip().split())

    # If we need to visit only 1 planet, any starting planet works
    if k == 1:
        return str(n % MOD)

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def count_ways(current, steps_left, visited_tuple):
        """
        Count ways to complete a sequence of length k ending at 'current'
        with 'steps_left' more planets to visit, given 'visited_tuple' planets are already visited.
        """
        if steps_left == 0:
            return 1

        count = 0
        # Next planet must be in range [1, min(n, current + m)]
        max_next = min(n, current + m)

        for next_plant in range(1, max_next + 1):
            if next_plant not in visited_tuple:
                new_visited = visited_tuple + (next_plant,)
                count = (count + count_ways(next_plant, steps_left - 1, new_visited)) % MOD

        return count

    total = 0
    for start in range(1, n + 1):
        visited = (start,)
        total = (total + count_ways(start, k - 1, visited)) % MOD

    return str(total)
